import fs from 'fs/promises';
import path from 'path';
import { randomBytes } from 'crypto';
import { spawn, type ChildProcess } from 'child_process';
import { createServer } from 'net';
import { subprocessEnvironment } from '../../utils/subprocessEnvironment';
import { once } from 'events';
import { setTimeout as delay } from 'timers/promises';
import { installMemoryComponents } from './memoryComponents';
import { MemoryModelService, type EngineBinding } from './MemoryModelService';
import type { ProfileAgent } from './ProfileAgent';
import type { ProfileRuntime } from '../../types/design-profile';
import { errnoCode } from '../../utils/errnoCode';

interface MemoryRuntimeOptions {
  directory: string;
  componentRoot: string;
  agent: ProfileAgent;
}
interface StartOptions {
  isDownloadAllowed?: boolean;
  onStarted?: () => void;
}
interface LaunchOptions extends StartOptions {
  isDownloadAllowed: boolean;
}
const START_TIMEOUT_MS = 60_000;
const REQUEST_TIMEOUT_MS = 30_000;
const READINESS_INTERVAL_MS = 200;
const EXIT_TIMEOUT_MS = 5_000;
const MAX_RESPONSE_BYTES = 4 * 1024 * 1024;

export class MemoryRuntime {
  private child?: ChildProcess;
  private provider?: MemoryModelService;
  private pending?: Promise<void>;
  private closing?: Promise<void>;
  private isPendingDownloadAllowed = true;
  private token = '';
  private base = '';
  private abort?: AbortController;
  private shutdownCount = 0;
  isReady = false;
  constructor(private readonly options: MemoryRuntimeOptions) {}

  start({
    isDownloadAllowed = true,
    onStarted,
  }: StartOptions = {}): Promise<void> {
    if (this.closing)
      return Promise.reject(
        new DOMException('Profile memory is closing', 'AbortError'),
      );
    if (this.isReady) return Promise.resolve();
    if (this.pending) {
      if (this.isPendingDownloadAllowed || !isDownloadAllowed)
        return this.pending;
      const shutdownCount = this.shutdownCount;
      return this.pending
        .catch(() => undefined)
        .then(() => {
          if (shutdownCount !== this.shutdownCount)
            throw new DOMException('Profile memory was closed', 'AbortError');
          return this.start({ isDownloadAllowed, onStarted });
        });
    }
    this.abort?.abort();
    this.abort = new AbortController();
    this.isPendingDownloadAllowed = isDownloadAllowed;
    this.pending = this.launch(this.abort.signal, {
      isDownloadAllowed,
      onStarted,
    })
      .catch(async (error: unknown) => {
        await this.stop();
        throw error;
      })
      .finally(() => {
        this.pending = undefined;
      });
    return this.pending;
  }

  async request<T>(
    runtime: ProfileRuntime,
    endpoint: string,
    body: unknown,
    method = 'POST',
    signal?: AbortSignal,
    binding?: EngineBinding,
  ): Promise<T> {
    if (!this.isReady || !this.provider)
      throw new Error(
        'Design profile memory is unavailable; enable or retry the profile',
      );
    const cancellation = AbortSignal.any([
      AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      ...(this.abort ? [this.abort.signal] : []),
      ...(signal ? [signal] : []),
    ]);
    return this.provider.withRuntime(
      runtime,
      () => this.fetch<T>(endpoint, body, method, cancellation),
      cancellation,
      binding,
    );
  }

  close(): Promise<void> {
    if (this.closing) return this.closing;
    this.shutdownCount += 1;
    this.abort?.abort();
    this.closing = Promise.resolve(this.pending)
      .catch(() => undefined)
      .then(() => this.stop())
      .finally(() => {
        this.closing = undefined;
      });
    return this.closing;
  }

  private async launch(
    signal: AbortSignal,
    { isDownloadAllowed, onStarted }: LaunchOptions,
  ): Promise<void> {
    await this.stop();
    const components = await installMemoryComponents({
      root: this.options.componentRoot,
      cancellation: signal,
      isDownloadAllowed,
    });
    const data = path.join(this.options.directory, 'engine');
    await fs.mkdir(data, { recursive: true, mode: 0o700 });
    const modelDirectory = path.join(data, 'models');
    try {
      await fs.symlink(components.models, modelDirectory, 'dir');
    } catch (error) {
      if (errnoCode(error) !== 'EEXIST') throw error;
    }
    const reservation = createServer();
    reservation.listen(0, '127.0.0.1');
    await once(reservation, 'listening');
    const address = reservation.address();
    if (!address || typeof address === 'string')
      throw new Error('Could not allocate profile memory port');
    await new Promise<void>((resolve) => reservation.close(() => resolve()));
    this.provider = new MemoryModelService(this.options.agent);
    const providerUrl = await this.provider.start();
    this.token = randomBytes(32).toString('hex');
    this.base = `http://127.0.0.1:${address.port}`;
    const env: NodeJS.ProcessEnv = {
      ...subprocessEnvironment('profileMemory'),
      SUPERMEMORY_DATA_DIR: data,
      SUPERMEMORY_PORT: String(address.port),
      SUPERMEMORY_DISABLE_TELEMETRY: '1',
      SUPERMEMORY_NO_OPEN: '1',
      SUPERMEMORY_NO_UPDATE_CHECK: '1',
      SUPERMEMORY_NO_STARTUP_ANIMATION: '1',
      SUPERMEMORY_EMBEDDING_PROVIDER: 'local',
      SUPERMEMORY_EMBEDDING_MODEL: 'Xenova/bge-base-en-v1.5',
      SUPERMEMORY_EMBEDDING_DIMENSIONS: '768',
      WORKFLOW_ENGINE: 'direct',
      RIVET_MEMORY_ACCESS_TOKEN: this.token,
      ANTHROPIC_API_KEY: this.provider.token,
      ANTHROPIC_BASE_URL: providerUrl,
    };
    const preload = path.resolve(
      __dirname,
      '../../../dist/services/profiles/engineAccess.js',
    );
    await fs.access(preload);
    signal.throwIfAborted();
    const child = spawn(components.binary, ['--preload', preload], {
      cwd: data,
      env,
      stdio: 'ignore',
    });
    this.child = child;
    child.once('exit', () => {
      this.isReady = false;
    });
    await once(child, 'spawn');
    onStarted?.();
    const deadline = Date.now() + START_TIMEOUT_MS;
    while (Date.now() < deadline) {
      signal.throwIfAborted();
      if (child.exitCode !== null || child.signalCode !== null)
        throw new Error('Design profile memory exited before readiness');
      try {
        await this.fetch(
          '/v4/memories/list',
          { containerTags: ['rivet-readiness'], limit: 1 },
          'POST',
          signal,
        );
        this.isReady = true;
        return;
      } catch {
        signal.throwIfAborted();
      }
      await delay(READINESS_INTERVAL_MS, undefined, { signal });
    }
    throw new Error(
      'Design profile memory did not become ready; retry profile setup',
    );
  }

  private async fetch<T>(
    endpoint: string,
    body: unknown,
    method: string,
    cancellation?: AbortSignal,
  ): Promise<T> {
    const signal = AbortSignal.any([
      AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      ...(cancellation ? [cancellation] : []),
    ]);
    const response = await fetch(`${this.base}${endpoint}`, {
      method,
      headers: {
        Authorization: `Bearer ${this.token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal,
    });
    if (!response.ok)
      throw new Error(`Profile memory operation failed (${response.status})`);
    if (!response.body)
      throw new Error('Profile memory returned an empty response');
    const reader = response.body.getReader();
    const chunks: Buffer[] = [];
    let size = 0;
    while (true) {
      const next = await reader.read();
      if (next.done) break;
      size += next.value.length;
      if (size > MAX_RESPONSE_BYTES) {
        await reader.cancel();
        throw new Error('Profile memory response exceeded its budget');
      }
      chunks.push(Buffer.from(next.value));
    }
    return JSON.parse(Buffer.concat(chunks).toString('utf8')) as T;
  }

  private async stop(): Promise<void> {
    this.isReady = false;
    const child = this.child;
    this.child = undefined;
    if (child?.pid && child.exitCode === null && child.signalCode === null) {
      const closed = once(child, 'exit');
      child.kill('SIGTERM');
      const timeout = setTimeout(() => child.kill('SIGKILL'), EXIT_TIMEOUT_MS);
      try {
        await closed;
      } finally {
        clearTimeout(timeout);
      }
    }
    await this.provider?.close();
    this.provider = undefined;
  }
}
